import sys
from itertools import combinations

def main():
    input = sys.stdin.read().split()
    ptr = 0
    n = int(input[ptr])
    ptr += 1
    k = int(input[ptr])
    ptr += 1

    c = [[0]*n for _ in range(n)]
    for i in range(n):
        for j in range(i+1, n):
            val = int(input[ptr])
            ptr += 1
            c[i][j] = val
            c[j][i] = val

    total_danger = 0
    count = 0

    for S in combinations(range(n), k):
        S = list(S)
        adjacent = None
        for x in range(n):
            valid = True
            for i in S:
                if c[x][i] == -1:
                    valid = False
                    break
            if valid:
                if adjacent is not None:
                    valid = False
                adjacent = x
        if adjacent is not None:
            danger = 0
            for i in S:
                danger += c[adjacent][i]
            total_danger += danger
            count += 1

    if count == 0:
        print(0)
    else:
        print(total_danger // count)

main()
